//! Arithmetic over the Galois field GF(256) used by QR codes.
//!
//! The field is generated by the primitive polynomial
//! `x^8 + x^4 + x^3 + x^2 + 1` (`0x11D`). Exponential and logarithm tables are
//! built once at compile time and every operation is a table lookup, so all
//! functions here are total and panic-free for the documented domains.

/// Primitive polynomial for GF(256): `x^8 + x^4 + x^3 + x^2 + 1`.
const PRIM: u16 = 0x11D;

/// The paired exponential (length 512, doubled) and logarithm (length 256)
/// lookup tables.
type Tables = ([u8; 512], [u8; 256]);

/// Builds the `(exp, log)` tables at compile time.
///
/// `exp` is doubled (length 512) so that `mul` can add two logarithms (each at
/// most 254) without a modulo reduction.
const fn build_tables() -> Tables {
    let mut exp = [0u8; 512];
    let mut log = [0u8; 256];
    let mut x: u16 = 1;
    let mut i = 0usize;
    while i < 255 {
        exp[i] = x as u8;
        log[x as usize] = i as u8;
        x <<= 1;
        if x & 0x100 != 0 {
            x ^= PRIM;
        }
        i += 1;
    }
    let mut j = 255usize;
    while j < 512 {
        exp[j] = exp[j - 255];
        j += 1;
    }
    (exp, log)
}

const TABLES: Tables = build_tables();
const EXP: [u8; 512] = TABLES.0;
const LOG: [u8; 256] = TABLES.1;

/// Field addition (and subtraction) — the carry-less XOR.
#[inline]
pub fn add(a: u8, b: u8) -> u8 {
    a ^ b
}

/// Returns `α^i`, the `i`-th power of the primitive element.
///
/// The exponent is reduced modulo 255 (`α^255 == 1`).
#[inline]
pub fn exp(i: u16) -> u8 {
    EXP[(i % 255) as usize]
}

/// Returns the discrete logarithm of `a` (the `i` such that `α^i == a`).
///
/// `a` must be non-zero; `log(0)` is undefined and returns `0`.
#[inline]
pub fn log(a: u8) -> u8 {
    LOG[a as usize]
}

/// Field multiplication.
#[inline]
pub fn mul(a: u8, b: u8) -> u8 {
    if a == 0 || b == 0 {
        0
    } else {
        EXP[LOG[a as usize] as usize + LOG[b as usize] as usize]
    }
}

/// Field division `a / b`.
///
/// Returns `0` when `a == 0`. `b` must be non-zero; dividing by zero returns
/// `0` rather than panicking.
#[inline]
pub fn div(a: u8, b: u8) -> u8 {
    if a == 0 || b == 0 {
        0
    } else {
        EXP[LOG[a as usize] as usize + 255 - LOG[b as usize] as usize]
    }
}

/// Multiplicative inverse `a^-1`.
///
/// `a` must be non-zero; `inv(0)` returns `0`.
#[inline]
pub fn inv(a: u8) -> u8 {
    if a == 0 {
        0
    } else {
        EXP[255 - LOG[a as usize] as usize]
    }
}

/// Raises `a` to the power `n`.
#[inline]
pub fn pow(a: u8, n: u32) -> u8 {
    if a == 0 {
        return if n == 0 { 1 } else { 0 };
    }
    EXP[((LOG[a as usize] as usize) * (n as usize % 255)) % 255]
}
